 ('agents.report.event_duplicate', 'en', 'When a possible duplicate arrives'),
 ('agents.report.event_duplicate', 'de', 'Wenn ein mögliches Duplikat eingeht'),
 ('agents.report.event_unapproved_supplier', 'en', 'When an invoice comes from an unapproved supplier'),
 ('agents.report.event_unapproved_supplier', 'de', 'Wenn eine Rechnung von einem nicht freigegebenen Lieferanten kommt'),
 ('agents.report.event_file_failed', 'en', 'When a supplier file cannot be read'),
 ('agents.report.event_file_failed', 'de', 'Wenn eine Lieferantendatei nicht gelesen werden kann'),
 ('agents.reporthint.event_stuck', 'en', 'Each invoice at one stage longer than the days chosen, told once per stay at that stage.'),
 ('agents.reporthint.event_stuck', 'de', 'Jede Rechnung, die länger als die gewählten Tage in einem Schritt liegt, einmal je Aufenthalt gemeldet.'),
 ('agents.reporthint.event_duplicate', 'en', 'Each invoice that looks like a duplicate of another, told once.'),
 ('agents.reporthint.event_duplicate', 'de', 'Jede Rechnung, die wie ein Duplikat einer anderen aussieht, einmal gemeldet.'),
 ('agents.reporthint.event_unapproved_supplier', 'en', 'Each invoice from a supplier not on file, or on hold, told once.'),
 ('agents.reporthint.event_unapproved_supplier', 'de', 'Jede Rechnung von einem nicht angelegten oder gesperrten Lieferanten, einmal gemeldet.'),
 ('agents.reporthint.event_file_failed', 'en', 'Each received file the Route monitor shows as failed or partly read in the last two weeks, told once. Needs access to the Route monitor.'),
 ('agents.reporthint.event_file_failed', 'de', 'Jede eingegangene Datei, die der Routenmonitor in den letzten zwei Wochen als fehlgeschlagen oder teilweise gelesen zeigt, einmal gemeldet. Erfordert Zugriff auf den Routenmonitor.'),
